const body = $input.first().json.body ?? $input.first().json;

const userID = Number(body.userId ?? body.UserID);
const watchID = Number(body.smartWatchId ?? body.SmartWatchID);
const phoneID = Number(body.androidId ?? body.AndroidID);
const type = String(body.sensorType ?? body.type ?? body.MonitoringType ?? '').trim();
const value = Number(body.value ?? body.Value ?? body.heartRate);

const valid = Number.isInteger(userID) && userID > 0 && Number.isInteger(watchID) && watchID > 0 && Number.isInteger(phoneID) && phoneID > 0 && type.length > 0 && Number.isFinite(value);

return [{ json: { userID, watchID, phoneID, type, value, valid } }];

const request = $('Normalize Input').first().json;
const mapping = $input.first().json ?? {};
const mappingId = Number(mapping.id ?? mapping.mapping_id ?? mapping.feedback_config_rule_id ?? 0);

if (!mappingId) {
  return [{ json: { statusCode: 404, response: { success: false, reason: 'mapping_not_found' } } }];
}

const minValue = Number(mapping.minvalue);
const maxValue = Number(mapping.maxvalue);
const value = request.value;

if (!Number.isFinite(minValue) || !Number.isFinite(maxValue)) {
  return [{ json: { statusCode: 500, response: { success: false, reason: 'mapping_test_failed' } } }];
}

if (value < minValue || value > maxValue) {
  return [{ json: { statusCode: 400, response: { success: false, reason: 'outside_range', minValue, maxValue } } }];
}

function mapValue(input, inMin, inMax, outMin, outMax) {
  const minimum = Number(outMin ?? 0);
  const maximum = Number(outMax ?? minimum);
  if (inMin === inMax) return minimum;
  return minimum + ((input - inMin) * (maximum - minimum)) / (inMax - inMin);
}

let pulses;
let intensity = Math.round(mapValue(value, minValue, maxValue, mapping.minintensity, mapping.maxintensity));
let duration = Math.round(mapValue(value, minValue, maxValue, mapping.minduration, mapping.maxduration));
let interval;

if (request.type.toLowerCase() === 'heartrate') {
  pulses = 10;
  interval = Math.max(0, Math.round((60000 / value) - duration));
} else {
  pulses = Math.round(mapValue(value, minValue, maxValue, mapping.minpulses, mapping.maxpulses));
  interval = Math.round(mapValue(value, minValue, maxValue, mapping.mininterval, mapping.maxinterval));
}

const response = {
  intensity,
  pulses,
  duration,
  interval,
  alertGiven: pulses > 0 ? 'yes' : 'no',
  fbRangeID: mappingId,
  monitoringType: request.type,
  type: request.type,
  value,
  userID: request.userID,
  SmartWatchID: request.watchID,
  AndroidID: request.phoneID
};

return [{ json: { statusCode: 200, response } }];
